# English section, grammar: spotting errors, fill in the blanks, sentence
# improvement, voice and narration, at the 10+2 CBSE level.
ERR = "The sentence below is divided into parts. Select the part that contains a grammatical error. If there is no error, select 'No error'.\n\n"
FILL = "Select the most appropriate option to fill in the blank.\n\n"
IMP = "Select the most appropriate option to replace the underlined part of the sentence. If no improvement is needed, select 'No improvement'.\n\n"
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Spotting errors", ERR + "The rifles in the armoury / was cleaned / every evening.",
      ["was cleaned", "The rifles in the armoury", "every evening.", "No error"],
      "The subject is 'rifles', which is plural; 'in the armoury' only describes them. So the verb must be plural: 'The rifles in the armoury were cleaned every evening.'"),
    S(1, 2, "Spotting errors", ERR + "The instructor / explained us / the new drill before the parade.",
      ["explained us", "The instructor", "the new drill before the parade.", "No error"],
      "'Explain' does not take the listener as a direct object. The person comes after 'to': 'The instructor explained the new drill to us before the parade.'"),
    S(1, 1, "Spotting errors", ERR + "The engineers who checked the aircraft / during the storm / were thanked by the commander.",
      ["No error", "The engineers who checked the aircraft", "during the storm", "were thanked by the commander."],
      "The sentence is correct. The plural subject 'engineers' takes the plural verb 'were thanked', and the relative clause 'who checked' is in the right tense."),
    S(1, 1, "Fill in the blanks", FILL + "The ground crew has been on duty ______ six hours.",
      ["for", "since", "from", "by"],
      "'For' is used with a length of time (for six hours). 'Since' marks the point in time when the action began (since 6 a.m.)."),
    S(1, 1, "Fill in the blanks", FILL + "The transport aircraft took ______ exactly at noon.",
      ["off", "up", "over", "after"],
      "'Take off' means to leave the ground and begin flying. 'Take up' means to start a hobby or job, 'take over' means to gain control, and 'take after' means to resemble a parent."),
    S(1, 2, "Fill in the blanks", FILL + "If the runway ______ dry, the aircraft would have landed safely.",
      ["had been", "was", "were", "has been"],
      "An unreal condition about the past (the third conditional) uses the past perfect in the if-clause with 'would have' + past participle: 'If the runway had been dry, the aircraft would have landed safely.'"),
    S(1, 1, "Sentence improvement", IMP + "The passing-out parade __has began__ on time.",
      ["has begun", "has beginned", "have begun", "No improvement"],
      "The present perfect needs the past participle. 'Begin' is irregular: begin, began (past), begun (past participle). The singular 'parade' takes 'has'."),
    S(1, 2, "Sentence improvement", IMP + "The instructor asked us __that we should not talk__ during the briefing.",
      ["not to talk", "to not talking", "that not talk", "No improvement"],
      "After 'asked' + object, a request is reported with a to-infinitive, and the negative goes before 'to': 'The instructor asked us not to talk during the briefing.'"),
    S(1, 1, "Active and passive voice", "Select the passive form of the sentence.\n\nThe technicians have checked the radar.",
      ["The radar has been checked by the technicians.", "The radar have been checked by the technicians.", "The radar was checked by the technicians.", "The radar is being checked by the technicians."],
      "Present perfect active ('have checked') becomes 'has/have been' + past participle. The new subject 'radar' is singular, so it takes 'has been'."),
    S(1, 2, "Direct and indirect speech", "Select the correct indirect form of the sentence.\n\nThe flight sergeant said to me, \"Report to the hangar at once.\"",
      ["The flight sergeant ordered me to report to the hangar at once.", "The flight sergeant ordered me that report to the hangar at once.", "The flight sergeant said me to report to the hangar at once.", "The flight sergeant ordered me that I reported to the hangar at once."],
      "An order is reported with 'ordered' (or 'told') + object + to-infinitive: 'The flight sergeant ordered me to report to the hangar at once.' 'Said me' is wrong because 'said' does not take a personal object."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Spotting errors", ERR + "My brother and I / goes / to the stadium every Sunday.",
      ["goes", "My brother and I", "to the stadium every Sunday.", "No error"],
      "Two subjects joined by 'and' make a plural subject, so the verb is 'go': 'My brother and I go to the stadium every Sunday.'"),
    S(2, 2, "Spotting errors", ERR + "Every officer and every airman / have to attend / the safety briefing.",
      ["have to attend", "Every officer and every airman", "the safety briefing.", "No error"],
      "When 'each' or 'every' comes before nouns joined by 'and', the verb stays singular: 'Every officer and every airman has to attend the safety briefing.'"),
    S(2, 2, "Spotting errors", ERR + "I have met / your cousin yesterday / at the railway station.",
      ["I have met", "your cousin yesterday", "at the railway station.", "No error"],
      "The present perfect cannot be used with a finished past time such as 'yesterday'. Use the simple past: 'I met your cousin yesterday.'"),
    S(2, 1, "Fill in the blanks", FILL + "Every cadet in the squadron takes pride ______ a smart turnout.",
      ["in", "at", "on", "with"],
      "The fixed phrase is 'take pride in' something: 'takes pride in a smart turnout'. 'Pride' is not followed by 'at', 'on' or 'with' in this sense."),
    S(2, 2, "Fill in the blanks", FILL + "The pilot was blamed ______ the delay, although the weather was the real cause.",
      ["for", "of", "with", "on"],
      "We blame a person for something: 'The pilot was blamed for the delay.' 'Blame it on' puts the thing first (blamed the delay on the pilot); 'accused of' is a different verb."),
    S(2, 1, "Fill in the blanks", FILL + "We will wait at the gate until the bus ______.",
      ["arrives", "will arrive", "arrived", "has been arriving"],
      "In a time clause after 'until', 'when' or 'as soon as', the simple present is used for a future event: 'until the bus arrives', not 'until the bus will arrive'."),
    S(2, 2, "Sentence improvement", IMP + "Physics __are__ my favourite subject.",
      ["is", "were", "have been", "No improvement"],
      "Names of subjects that end in -ics, such as physics, mathematics and economics, are singular when they mean the subject: 'Physics is my favourite subject.'"),
    S(2, 1, "Sentence improvement", IMP + "All the equipment __were checked__ before the flight.",
      ["was checked", "were check", "have checked", "No improvement"],
      "'Equipment' is an uncountable noun and takes a singular verb: 'All the equipment was checked before the flight.' It has no plural form 'equipments'."),
    S(2, 2, "Active and passive voice", "Select the passive form of the sentence.\n\nDid the engineers inspect the runway?",
      ["Was the runway inspected by the engineers?", "Did the runway inspected by the engineers?", "Was the runway inspect by the engineers?", "Has the runway been inspecting by the engineers?"],
      "A simple past question with 'did' becomes 'was/were' + subject + past participle in the passive: 'Was the runway inspected by the engineers?'"),
    S(2, 1, "Direct and indirect speech", "Select the correct indirect form of the sentence.\n\nPriya said, \"I am reading a novel.\"",
      ["Priya said that she was reading a novel.", "Priya said that she is reading a novel.", "Priya said that I was reading a novel.", "Priya said that she has been reading a novel."],
      "With a past reporting verb, 'I' becomes 'she' and the present continuous 'am reading' moves back to the past continuous 'was reading'."),

    # ---------- Drill only ----------
    S(0, 2, "Spotting errors", ERR + "The hostel warden / gave us / a few advices before the trek.",
      ["a few advices before the trek.", "The hostel warden", "gave us", "No error"],
      "'Advice' is uncountable, so it has no plural and does not take 'a few'. Say 'some advice' or 'a few pieces of advice'."),
    S(0, 2, "Spotting errors", ERR + "The recruits were told / to report at sharp 6 a.m. / on the parade ground.",
      ["to report at sharp 6 a.m.", "The recruits were told", "on the parade ground.", "No error"],
      "'Sharp' meaning exactly comes after the time: 'to report at 6 a.m. sharp'."),
    S(0, 1, "Fill in the blanks", FILL + "The flight was cancelled ______ heavy fog.",
      ["due to", "because", "since", "so that"],
      "'Due to' is followed by a noun phrase (heavy fog). 'Because' and 'since' need a full clause ('because the fog was heavy'), and 'so that' shows purpose."),
    S(0, 1, "Fill in the blanks", FILL + "Of all the runways at this airfield, the new one is the ______.",
      ["longest", "longer", "most long", "more longer"],
      "'Of all the runways' compares one with every other, so the superlative is needed. Short adjectives add -est: 'the longest'. 'More longer' marks the comparison twice."),
    S(0, 1, "Fill in the blanks", FILL + "The squadron welcomed ______ European delegation last week.",
      ["a", "an", "much", "few"],
      "'European' begins with the sound /j/ (you-), a consonant sound, so it takes 'a', as in 'a uniform' and 'a university'. The article depends on the sound, not the letter. 'Much' and 'few' do not go with a singular countable noun."),
    S(0, 2, "Sentence improvement", IMP + "Please __reply my letter__ as soon as you can.",
      ["reply to my letter", "reply for my letter", "replying my letter", "No improvement"],
      "'Reply' needs 'to' before the thing answered: 'Please reply to my letter.' Compare 'answer my letter', which takes no preposition."),
    S(0, 1, "Active and passive voice", "Select the passive form of the sentence.\n\nThey will announce the results tomorrow.",
      ["The results will be announced tomorrow.", "The results will announced tomorrow.", "The results would be announced tomorrow.", "The results are announced tomorrow."],
      "Simple future active ('will announce') becomes 'will be' + past participle. The vague agent 'they' is usually dropped in the passive."),
    S(0, 2, "Direct and indirect speech", "Select the correct indirect form of the sentence.\n\nThe teacher said, \"Light travels faster than sound.\"",
      ["The teacher said that light travels faster than sound.", "The teacher said that light travelled faster than sound.", "The teacher said that light had travelled faster than sound.", "The teacher said that light was travelling faster than sound."],
      "A universal truth keeps its present tense in reported speech even after a past reporting verb: 'light travels faster than sound'."),
]
